const fs = require("fs");
const path = require("path");

const { withDangerousMod } = require("expo/config-plugins");

/**
 * Pins the Gradle daemon to Java 17 on every developer machine.
 *
 * The Android build fails under newer JDKs (the Android JDK image transform and
 * CMake configure steps break), and `android/` is generated, so the criteria
 * file has to be rewritten on each prebuild rather than committed.
 */
const CONTENTS = [
  "# Generated by plugins/with-gradle-daemon-jvm.js — do not edit by hand.",
  "# The Android toolchain requires Java 17; Gradle locates or provisions it.",
  "toolchainVersion=17",
  "",
].join("\n");

module.exports = function withGradleDaemonJvm(config) {
  return withDangerousMod(config, [
    "android",
    (modConfig) => {
      const target = path.join(
        modConfig.modRequest.platformProjectRoot,
        "gradle",
        "gradle-daemon-jvm.properties",
      );
      fs.mkdirSync(path.dirname(target), { recursive: true });
      fs.writeFileSync(target, CONTENTS);
      return modConfig;
    },
  ]);
};
